class MathOperations {
    // Compile-time polymorphism: Method Overloading
    public int multiply(int a, int b) { return a * b; }
    public double multiply(double a, double b) { return a * b; }
}

class Speaker {
    // Base for runtime polymorphism
    public void emitSound() { System.out.println("Generic speaker hum"); }
}

class BassWoofer extends Speaker {
    // Runtime polymorphism: Method Overriding
    public void emitSound() { System.out.println("Deep thumping bass (80Hz)"); }
}

public class DualPolymorphismDemo {
    public static void main(String[] args) {
        // Compile-time resolution: resolved during compilation
        MathOperations math = new MathOperations();
        System.out.println("Multiply ints: " + math.multiply(4, 5));
        System.out.println("Multiply doubles: " + math.multiply(2.5, 4.0));

        // Runtime resolution: resolved by JVM during execution
        Speaker spk = new BassWoofer();
        spk.emitSound();
    }
}

