class Drone {
    protected String droneId;
    public Drone(String id) { this.droneId = id; }
    public void executeMission() {
        System.out.println("Drone " + droneId + ": Standing by for generic mission");
    }
}

class SurveillanceDrone extends Drone {
    public SurveillanceDrone(String id) { super(id); }
    public void executeMission() {
        System.out.println("Drone " + droneId + ": Performing aerial perimeter surveillance");
    }
}

class DeliveryDrone extends Drone {
    public DeliveryDrone(String id) { super(id); }
    public void executeMission() {
        System.out.println("Drone " + droneId + ": Delivering package to coordinate (37.77, -122.41)");
    }
}

class AgriculturalDrone extends Drone {
    public AgriculturalDrone(String id) { super(id); }
    public void executeMission() {
        System.out.println("Drone " + droneId + ": Dispersing automated crop irrigation");
    }
}

public class Main {
    public static void main(String[] args) {
        Drone[] fleet = new Drone[] {
            new SurveillanceDrone("SURV-01"),
            new DeliveryDrone("DELIV-02"),
            new AgriculturalDrone("AGRI-03")
        };
        for (Drone d : fleet) {
            d.executeMission();
        }
    }
}
